     1|/**
     2| * IVX IA Conversation Brain — general-purpose, owner-token-gated direct answers.
     3| *
     4| * Owner spec:
     5| *   - The brain can have regular conversation and answer ANY type of question.
     6| *   - If it can be answered deterministically (math, general knowledge, greeting,
     7| *     help, capabilities), answer directly — never route to the bearer-guarded
     8| *     pipeline that returns 401 for owner-token-only requests.
     9| *
    10| * This is a fast, deterministic path that runs AFTER the identity/senior-dev
    11| * brains but BEFORE the Supabase-bearer-guarded main pipeline. It never blocks
    12| * and never asks for proof — it is the IVX IA conversational persona.
    13| */
    14|
    15|export const IVX_IA_CONVERSATION_MARKER = 'ivx-ia-conversation-brain-2026-07-06';
    16|
    17|/**
    18| * Detect a general conversation question that can be answered deterministically.
    19| * Returns the question type or 'none'.
    20| */
    21|export type IVXConversationType =
    22|  | 'math'
    23|  | 'percentage'
    24|  | 'greeting'
    25|  | 'thanks'
    26|  | 'capabilities'
    27|  | 'help'
    28|  | 'yes_no'
    29|  | 'definition'
    30|  | 'none';
    31|
    32|export function detectIVXConversationQuestion(message: string): IVXConversationType {
    33|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.%]/g, ' ');
    34|  const compact = text.replace(/\s+/g, ' ').trim();
    35|  if (!compact) return 'none';
    36|
    37|  // DEF-IA-05 fix: Explicit "yes or no" prefix must be checked BEFORE math.
    38|  // Otherwise "yes or no, can IVX IA work 24/7" is parsed as 24÷7=3.428571
    39|  // because the sanitizer keeps the '/' character and detectMathQuestion
    40|  // greedily matches "24/7" as a symbol-form division.
    41|  if (/^yes\s+or\s+no\b/.test(compact)) return 'yes_no';
    42|
    43|  // Math: "15 multiplied by 3", "15 * 3", "what is 15 x 3", "10 plus 5",
    44|  // "100 minus 20", "50 divided by 2", "square root of 144"
    45|  if (detectMathQuestion(compact)) return 'math';
    46|
    47|  // Percentage: "what is 15% of 50000", "15 percent of 80000"
    48|  // Check BEFORE definition — "what is 15% of 50000" starts with "what is"
    49|  if (detectPercentageQuestion(compact)) return 'percentage';
    50|
    51|  // Yes/No: simple questions that can be answered yes or no
    52|  if (detectYesNoQuestion(compact)) return 'yes_no';
    53|
    54|  // Definition: "what is a REIT", "define DST", "what does JV mean"
    55|  if (detectDefinitionQuestion(compact)) return 'definition';
    56|
    57|  // Greetings
    58|  const greetings = ['hello', 'hi ', 'hey', 'hola', 'good morning', 'good afternoon', 'good evening', 'buenos dias', 'buenas tardes'];
    59|  if (greetings.some((g) => compact === g.trim() || compact.startsWith(g) || compact === g.trim())) return 'greeting';
    60|
    61|  // Thanks
    62|  const thanks = ['thank you', 'thanks', 'gracias', 'much appreciated', 'ty '];
    63|  if (thanks.some((t) => compact === t.trim() || compact.startsWith(t))) return 'thanks';
    64|
    65|  // Capabilities / "what can you do"
    66|  const capPhrases = ['what can you do', 'what do you do', 'help me with', 'your capabilities', 'what are your features', 'what are you able to do', 'que puedes hacer'];
    67|  if (capPhrases.some((p) => compact.includes(p))) return 'capabilities';
    68|
    69|  // Help
    70|  if (compact === 'help' || compact.startsWith('help ') || compact.includes('can you help')) return 'help';
    71|
    72|  return 'none';
