    75|/**
    76| * Detect and evaluate a math question.
    77| * Handles: plus, minus, multiplied by, times, divided by, x, *, /, +, -, sqrt.
    78| */
    79|function detectMathQuestion(compact: string): boolean {
    80|  // Word-form arithmetic
    81|  const wordMath = /\b(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/;
    82|  if (wordMath.test(compact)) return true;
    83|  // Symbol-form arithmetic (single regex test — removed redundant double check)
    84|  const symMath = /\b(\d+(?:\.\d+)?)\s*[+\-*/x]\s*(\d+(?:\.\d+)?)/;
    85|  if (symMath.test(compact)) return true;
    86|  // "what is N op N"
    87|  if (/\bwhat is\s+/.test(compact) && wordMath.test(compact)) return true;
    88|  // square root
    89|  if (/\b(square root|sqrt)\s+of\s+\d+/.test(compact)) return true;
    90|  return false;
    91|}
