   100|/**
   101| * Evaluate a percentage expression from natural language.
   102| */
   103|function evaluatePercentageQuestion(message: string): number | null {
   104|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s%.]/g, ' ').replace(/\s+/g, ' ').trim();
   105|  const match = text.match(/(\d+(?:\.\d+)?)\s*(?:%|percent)\s+of\s+(\d+(?:\.\d+)?)/);
   106|  if (!match) return null;
   107|  const pct = parseFloat(match[1]);
   108|  const base = parseFloat(match[2]);
   109|  if (!isFinite(pct) || !isFinite(base)) return null;
   110|  return (pct / 100) * base;
   111|}
