   113|/**
   114| * Detect a yes/no question that can be answered deterministically.
   115| */
   116|function detectYesNoQuestion(compact: string): boolean {
   117|  // "is ivx a reit", "can i invest", "does ivx offer tokenization"
   118|  if (/^(is|are|can|do|does|will|should|has|have)\b/.test(compact) && compact.length < 120) return true;
   119|  return false;
   120|}
