   122|/**
   123| * Answer a yes/no question about IVX.
   124| */
   125|function answerYesNoQuestion(message: string): string | null {
   126|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim();
   127|  // IVX-specific yes/no answers
   128|  if (/\b(is|are)\b.*\b(reit|dst|1031)\b/.test(text)) {
   129|    return 'No, IVX Holdings is not a REIT or DST. IVX is a real-estate joint-venture platform that offers fractional ownership in specific projects, not a traded trust entity.';
   130|  }
   131|  if (/\bcan\b.*\b(invest|buy|participate)\b/.test(text)) {
   132|    return 'Yes, you can invest through IVX Holdings by reviewing available projects and participating with fractional ownership. Visit ivxholding.com to see current offerings.';
   133|  }
   134|  if (/\b(does|do)\b.*\b(tokeniz|wallet|withdraw|wire)/.test(text)) {
   135|    return 'Yes, IVX Holdings supports tokenization, wallet management, withdrawals, and wire transfers for qualified investors.';
   136|  }
   137|  if (/\b(is|are)\b.*\b(legit|safe|secure|regulated)\b/.test(text)) {
   138|    return 'Yes, IVX Holdings operates with proper corporate structure and compliance. All investments are documented through formal JV agreements.';
   139|  }
   140|  // DEF-IA-05 fix: "can IVX IA work 24/7" — the '24/7' was stripped to '24 7'
   141|  // by the sanitizer; match on 'work' + '24 7' or '24 7' context.
   142|  if (/\bcan\b.*\b(work|operate|run|function)\b.*\b(24\s*7|around the clock|all day|nonstop|continuously)\b/.test(text)) {
   143|    return 'Yes, IVX IA can work 24/7. The AI brain is always available to answer questions, analyze deals, and assist investors — no business hours required.';
   144|  }
   145|  // Generic fallback — don't guess, route to AI
   146|  return null;
