   187|function evaluateMathQuestion(message: string): number | null {
   188|  const text = (message ?? '').toLowerCase().replace(/[^a-z0-9\s+\-*/=.]/g, ' ').replace(/\s+/g, ' ').trim();
   189|  // square root
   190|  const sqrtMatch = text.match(/(?:square root|sqrt)\s+of\s+(\d+(?:\.\d+)?)/);
   191|  if (sqrtMatch) {
   192|    const n = parseFloat(sqrtMatch[1]);
   193|    return Math.sqrt(n);
   194|  }
   195|  // word-form
   196|  const wordMatch = text.match(/(\d+(?:\.\d+)?)\s+(plus|minus|multiplied by|times|divided by|added to|subtracted from)\s+(\d+(?:\.\d+)?)/);
   197|  if (wordMatch) {
   198|    const a = parseFloat(wordMatch[1]);
   199|    const op = wordMatch[2];
   200|    const b = parseFloat(wordMatch[3]);
