   210|  if (symMatch) {
   211|    const a = parseFloat(symMatch[1]);
   212|    const op = symMatch[2];
   213|    const b = parseFloat(symMatch[3]);
   214|    switch (op) {
   215|      case '+': return a + b;
   216|      case '-': return a - b;
   217|      case '*': case 'x': return a * b;
   218|      case '/': return b === 0 ? null : a / b;
   219|    }
   220|  }
   221|  return null;
