     1|/**
     2| * IVX Live Context Injector — Production Awareness for IVX IA Chat
     3| *
     4| * Owner mandate 2026-07-30: IVX IA must always know the current production
     5| * state, autonomous jobs, deployment SHA, health, and pending approvals.
     6| *
     7| * V2 fix: Uses in-process production state (ivx-production-state.ts) instead
     8| * of HTTP fetches to localhost. The HTTP approach failed on Render because
     9| * the server can't call its own endpoints reliably during request processing.
    10| *
    11| * Phases covered:
    12| *   Phase 4 — Context Memory: current project, deployment, production state
    13| *   Phase 5 — Autonomous Integration: what workers are doing
    14| *   Phase 6 — Production Awareness: SHA, health, jobs, deployments
    15| */
    16|
    17|import { getProductionState, type ProductionState } from './ivx-production-state';
    18|
    19|export const IVX_LIVE_CONTEXT_MARKER = 'ivx-live-context-injector-v2-2026-07-30';
    20|
    21|/**
    22| * Build the [IVX LIVE PRODUCTION CONTEXT] block from in-process state.
    23| * This is synchronous — no HTTP calls, no async, no network dependency.
    24| */
    25|export function buildLiveContextBlock(): string {
    26|  const state = getProductionState();
    27|  const timestamp = new Date().toISOString();
    28|
    29|  if (!state) {
    30|    return [
    31|      '[IVX LIVE PRODUCTION CONTEXT]',
    32|      `  Note: Production state not yet initialized.`,
    33|      `  Timestamp: ${timestamp}`,
    34|      '[/IVX LIVE PRODUCTION CONTEXT]',
    35|    ].join('\n');
    36|  }
    37|
    38|  const lines: string[] = [
    39|    '[IVX LIVE PRODUCTION CONTEXT]',
    40|  ];
    41|
    42|  // Production health
    43|  lines.push(`  Production Health:`);
    44|  lines.push(`    Status: ${state.status}`);
    45|  lines.push(`    Commit SHA: ${state.commit.slice(0, 12)}`);
    46|  lines.push(`    Full SHA: ${state.commit}`);
    47|  lines.push(`    Boot Time: ${state.bootTime}`);
    48|  lines.push(`    Environment: ${state.environment}`);
    49|  lines.push(`    Service: ${state.serviceName}`);
    50|
    51|  // Autonomous QA scheduler
    52|  lines.push(`  Autonomous QA Scheduler:`);
    53|  lines.push(`    Running: ${state.schedulerRunning}`);
    54|  lines.push(`    Process Started: ${state.processStartedAt}`);
    55|
    56|  // Health markers (deploy proof)
    57|  if (state.healthMarkers && Object.keys(state.healthMarkers).length > 0) {
    58|    lines.push(`  Deploy Markers (proof of what's live):`);
    59|    for (const [key, value] of Object.entries(state.healthMarkers)) {
    60|      lines.push(`    ${key}: ${value}`);
    61|    }
    62|  }
    63|
    64|  lines.push(`  Context fetched at: ${timestamp}`);
    65|  lines.push('[/IVX LIVE PRODUCTION CONTEXT]');
    66|
    67|  return lines.join('\n');
    68|}
