    71| * Async wrapper for compatibility with the existing call site in ivx-owner-ai.ts.
    72| * Returns the same result as buildLiveContextBlock() — kept async so the
    73| * caller doesn't need to change its await pattern.
    74| */
    75|export async function getLiveContextBlock(): Promise<string> {
    76|  return buildLiveContextBlock();
